  public:
   const char* Name() const override { return "CountedMemoryAllocator"; }

   void* Allocate(size_t size) override {
     num_allocations_++;
     return static_cast<void*>(new char[size]);
   }

   void Deallocate(void* p) override {
     num_deallocations_++;
     delete[] static_cast<char*>(p);
   }

