     RecordTick(stats_, COMPACT_READ_BYTES_MARKED, IOSTATS(bytes_read));
     RecordTick(stats_, COMPACT_WRITE_BYTES_MARKED, IOSTATS(bytes_written));
   } else if (compaction_reason == CompactionReason::kPeriodicCompaction) {
