       // Reset().
       ASSERT_OK(Put("hello", "rocksdb"));
       ASSERT_EQ(1, TestGetTickerCount(options, NUMBER_KEYS_WRITTEN));
       options.statistics->histogramData(DB_WRITE, &histogram_data);
       ASSERT_GT(histogram_data.max, 0.0);
       options.statistics->Reset();
     }
   }
